/// <summary>
/// Lưu phần thông tin chung (header) và tab Lý lịch — không đụng tab HĐ, lương, file, ...
/// </summary>
private void SaveHeaderAndLyLich()
{
    if (!WebGlobal.HasPermission(PERMISSION_EDIT))
    {
        MsgBox.ShowWarning("Bạn không có quyền sửa hồ sơ nhân sự.");
        return;
    }

    if (!ValidateHeaderForSave())
        return;

    long employeeId;
    if (!long.TryParse(hidEmployeeID.Value, out employeeId) || employeeId <= 0)
    {
        MsgBox.ShowWarning("Mã nhân sự không hợp lệ.");
        return;
    }

    itemEmployeeEditing = new HRS_Employee();
    itemEmployeeEditing.EmployeeID = employeeId;
    if (!itemEmployeeEditing.Get())
    {
        MsgBox.ShowError("Không tải được dữ liệu để lưu.");
        return;
    }

    ApplyHeaderToEmployee(itemEmployeeEditing);
    ucTabLyLich.ApplyLyLichToEmployee(itemEmployeeEditing);

    SessionUser objUser = Session[Globals.USER] as SessionUser;
    if (objUser != null)
        itemEmployeeEditing.UpdatedUser = objUser.UserName;

    if (!itemEmployeeEditing.BeginTransaction())
    {
        string msg = itemEmployeeEditing.ErrorException != null
            ? itemEmployeeEditing.ErrorException.Message
            : "Không mở được giao dịch.";
        MsgBox.ShowError("Lỗi khi lưu: " + msg);
        return;
    }

    try
    {
        if (!itemEmployeeEditing.Update())
        {
            itemEmployeeEditing.RollBackTransaction();
            string msg = itemEmployeeEditing.ErrorException != null
                ? itemEmployeeEditing.ErrorException.Message
                : "Cập nhật thất bại.";
            if (msg.Contains("uq_EmployeeCode"))
                MsgBox.ShowWarning("Trùng mã nhân viên.");
            else
                MsgBox.ShowError("Lỗi khi lưu: " + msg);
            return;
        }

        itemEmployeeEditing.CommitTransaction();
        lblFullName.Text = Safe(itemEmployeeEditing.Fullname);
        MsgBox.ShowInfo("Đã lưu thông tin nhân viên và tab lý lịch.");
    }
    catch (Exception ex)
    {
        try
        {
            itemEmployeeEditing.RollBackTransaction();
        }
        catch
        {
        }
        MsgBox.ShowError("Lỗi khi lưu: " + ex.Message);
    }
}

private bool ValidateHeaderForSave()
{
    if (string.IsNullOrWhiteSpace(txtFirstName.Text))
    {
        MsgBox.ShowWarning("Bạn phải nhập họ nhân viên.");
        return false;
    }
    if (string.IsNullOrWhiteSpace(txtLastName.Text))
    {
        MsgBox.ShowWarning("Bạn phải nhập tên nhân viên.");
        return false;
    }
    return true;
}

