/// <summary>
/// Nạp lại dữ liệu từ DB — hủy thay đổi chưa lưu trên form.
/// </summary>
private void ReloadEmployeeFromServer()
{
    if (Session[Globals.USER] == null)
    {
        MsgBox.ShowWarning("Bạn cần đăng nhập để nạp lại hồ sơ.");
        return;
    }

    long employeeId;
    if (!long.TryParse(hidEmployeeID.Value, out employeeId) || employeeId <= 0)
    {
        long? resolvedId = ResolveEmployeeId();
        if (resolvedId == null || resolvedId.Value <= 0)
        {
            MsgBox.ShowWarning("Không xác định được mã nhân sự.");
            return;
        }
        employeeId = resolvedId.Value;
        hidEmployeeID.Value = employeeId.ToString();
    }

    LoadReferenceData(true);
    LoadEmployeeData(employeeId);
    MsgBox.ShowInfo("Đã nạp lại dữ liệu hồ sơ.");
}

