using System;
using System.Data;
using System.Globalization;
using System.Web.UI;
using System.Web.UI.WebControls;
using TKSObject;

namespace InformationWeb.Controls.Employee_V2
{
    /// <summary>
    /// Tab quá trình lương — chỉ xem. Cùng store/lưới WinForm frmEmployeeDetail (tpContract).
    /// </summary>
    public partial class TabQuaTrinhLuong : UserControl
    {
        /// <summary>Trùng InitGridColumn WinForm: gvContract.</summary>
        public const string GridQueryName = "HRS_EmployeeDetail_Contract";

        private const string StoreSearchForEmployee = "HRS_Contract_SearchForEmployee";

        private readonly HRS_Employee employeeDao = new HRS_Employee();

        protected void Page_Load(object sender, EventArgs e)
        {
        }

        public void BindForEmployee(long employeeId)
        {
            DataTable dt = null;
            try
            {
                dt = employeeDao.GetDataTable(StoreSearchForEmployee, "@EmployeeID", employeeId);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabQuaTrinhLuong.BindForEmployee: " + ex.Message);
            }

            if (dt == null)
                dt = new DataTable();

            EmployeeV2WebGrid.BindGridView(gvQuaTrinhLuong, GridQueryName, dt, false);

            if (gvQuaTrinhLuong.Columns.Count == 0 || gvQuaTrinhLuong.AutoGenerateColumns)
            {
                ApplyFallbackColumns();
                gvQuaTrinhLuong.DataSource = dt;
                gvQuaTrinhLuong.DataBind();
            }
        }

        private void ApplyFallbackColumns()
        {
            gvQuaTrinhLuong.AutoGenerateColumns = false;
            gvQuaTrinhLuong.Columns.Clear();

            AddBoundColumn("ContractNo", "Số hợp đồng");
            AddBoundColumn("ContractTypeName", "Loại hợp đồng");
            AddBoundColumn("SalaryQuotaCode", "Ngạch");
            AddBoundColumn("SalaryLevel", "Bậc");
            AddTemplateColumn("SalaryRatio", "Hệ số lương", FormatDecimal2);
            AddTemplateColumn("Salary", "Lương", FormatDecimal2);
            AddTemplateColumn("ContractDate", "Ngày hợp đồng", FormatDate);
            AddTemplateColumn("ExpiredDate", "Ngày hết HĐ", FormatDate);
        }

        private void AddBoundColumn(string fieldName, string headerText)
        {
            BoundField col = new BoundField();
            col.DataField = fieldName;
            col.HeaderText = headerText;
            col.HtmlEncode = true;
            gvQuaTrinhLuong.Columns.Add(col);
        }

        private void AddTemplateColumn(string fieldName, string headerText, string formatMethod)
        {
            TemplateField col = new TemplateField();
            col.HeaderText = headerText;
            col.ItemTemplate = new GridViewFormatTemplate(fieldName, formatMethod);
            gvQuaTrinhLuong.Columns.Add(col);
        }

        private static string FormatDecimal2(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            decimal d;
            if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
            {
                if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
                    return value.ToString();
            }
            return d.ToString("N2", CultureInfo.InvariantCulture);
        }

        private static string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            DateTime d;
            if (!DateTime.TryParse(value.ToString(), out d))
                return value.ToString();
            return d.ToString("dd/MM/yyyy");
        }

        private sealed class GridViewFormatTemplate : ITemplate
        {
            private readonly string fieldName;
            private readonly string formatMethod;

            public GridViewFormatTemplate(string fieldName, string formatMethod)
            {
                this.fieldName = fieldName;
                this.formatMethod = formatMethod;
            }

            public void InstantiateIn(Control container)
            {
                Literal lit = new Literal();
                lit.DataBinding += new EventHandler(Lit_DataBinding);
                container.Controls.Add(lit);
            }

            private void Lit_DataBinding(object sender, EventArgs e)
            {
                Literal lit = (Literal)sender;
                GridViewRow row = (GridViewRow)lit.NamingContainer;
                object value = DataBinder.Eval(row.DataItem, fieldName);

                if (formatMethod == "FormatDecimal2")
                    lit.Text = FormatDecimal2(value);
                else if (formatMethod == "FormatDate")
                    lit.Text = FormatDate(value);
                else
                    lit.Text = value == null || value == DBNull.Value ? "" : value.ToString();
            }
        }
    }
}

