    return key;
}

private void ApplyActiveTabUi(string tabKey, bool reloadViewTabData)
{
    bool isLyLich = tabKey == TabLyLichKey;
    bool isQuaTrinhLuong = tabKey == TabQuaTrinhLuongKey;

    if (!isLyLich && !isQuaTrinhLuong)
