using System;
using System.Data;
using System.Globalization;
using System.Text;
using System.Web;

namespace InformationWeb.Controls.Employee_V2
{
    /// <summary>
    /// Render DataTable thành bảng HTML (view-only), cột khai báo tường minh — dễ sửa hơn GridView/SYS_GridColumn.
    /// </summary>
    public static class EmployeeV2ViewTable
    {
        public enum ValueFormat
        {
            Text,
            Date,
            Decimal2,
            BoolYesNo
        }

        public sealed class ColumnSpec
        {
            public string FieldName;
            public string Caption;
            public ValueFormat Format;

            public ColumnSpec(string fieldName, string caption, ValueFormat format)
            {
                FieldName = fieldName;
                Caption = caption;
                Format = format;
            }
        }

        public static string BuildHtml(DataTable dt, ColumnSpec[] columns, string tableCssClass, bool showStt)
        {
            if (columns == null || columns.Length == 0)
                return "";

            StringBuilder sb = new StringBuilder();
            sb.Append("<div class=\"table-responsive\">");
            sb.Append("<table class=\"");
            sb.Append(HttpUtility.HtmlAttributeEncode(tableCssClass));
            sb.Append("\">");

            sb.Append("<thead><tr>");
            if (showStt)
                sb.Append("<th class=\"empv2-col-stt\">STT</th>");
            for (int c = 0; c < columns.Length; c++)
            {
                sb.Append("<th>");
                sb.Append(HttpUtility.HtmlEncode(columns[c].Caption));
                sb.Append("</th>");
            }
            sb.Append("</tr></thead><tbody>");

            if (dt == null || dt.Rows.Count == 0)
            {
                int colspan = columns.Length + (showStt ? 1 : 0);
                sb.Append("<tr><td colspan=\"");
                sb.Append(colspan.ToString(CultureInfo.InvariantCulture));
                sb.Append("\" class=\"text-center text-muted py-3\">Không có dữ liệu</td></tr>");
            }
            else
            {
                for (int r = 0; r < dt.Rows.Count; r++)
                {
                    DataRow row = dt.Rows[r];
                    sb.Append("<tr>");
                    if (showStt)
                    {
                        sb.Append("<td class=\"empv2-col-stt text-center\">");
                        sb.Append((r + 1).ToString(CultureInfo.InvariantCulture));
                        sb.Append("</td>");
                    }
                    for (int c = 0; c < columns.Length; c++)
                    {
                        sb.Append("<td>");
                        sb.Append(FormatCell(row, columns[c]));
                        sb.Append("</td>");
                    }
                    sb.Append("</tr>");
                }
            }

            sb.Append("</tbody></table></div>");
            return sb.ToString();
        }

        private static string FormatCell(DataRow row, ColumnSpec col)
        {
            if (row == null || col == null || string.IsNullOrEmpty(col.FieldName))
                return "";

            if (!row.Table.Columns.Contains(col.FieldName))
                return "";

            object value = row[col.FieldName];
            if (value == null || value == DBNull.Value)
                return "";

            switch (col.Format)
            {
                case ValueFormat.Date:
                    return HttpUtility.HtmlEncode(FormatDate(value));
                case ValueFormat.Decimal2:
                    return HttpUtility.HtmlEncode(FormatDecimal2(value));
                case ValueFormat.BoolYesNo:
                    return FormatBool(value);
                default:
                    return HttpUtility.HtmlEncode(value.ToString().Trim());
            }
        }

        private static string FormatDecimal2(object value)
        {
            decimal d;
            if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
            {
                if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
                    return value.ToString();
            }
            return d.ToString("N2", CultureInfo.InvariantCulture);
        }

        private static string FormatDate(object value)
        {
            DateTime d;
            if (!DateTime.TryParse(value.ToString(), out d))
                return value.ToString();
            return d.ToString("dd/MM/yyyy");
        }

        private static string FormatBool(object value)
        {
            bool b = false;
            if (value is bool)
                b = (bool)value;
            else
            {
                string s = value.ToString().Trim();
                if (s == "1" || string.Equals(s, "true", StringComparison.OrdinalIgnoreCase))
                    b = true;
            }
            if (b)
                return "<i class=\"bi bi-check-square-fill text-success\" aria-hidden=\"true\"></i>";
            return "<i class=\"bi bi-square text-muted\" aria-hidden=\"true\"></i>";
        }
    }
}

